/**
 * Set The Uniform Type Identifier
 *
 * @param uti
 */
void setUniformTypeIdentifier(String v) {
    if (v == null) {
        throw new IllegalArgumentException("Uniform Type Identifier is missing");
    }
    uti = v;
}
